// Webhook output nests request body under .body, so unwrap first
const raw = $input.item.json;
const d = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const title = (d.title || '').toLowerCase();
const notes = (d.notes || '').toLowerCase();
const employees = parseInt(d.employees || d.company_size || 0);
const industry = (d.industry || '').toLowerCase();

let score = 0;

// Title scoring
if (/\b(ceo|coo|cfo|cto|chief|founder|president)\b/.test(title)) score += 30;
else if (/\b(vp|vice president|senior director|head of)\b/.test(title)) score += 20;
else if (/\b(director|manager)\b/.test(title)) score += 5;

// Company size
if (employees >= 50 && employees <= 5000) score += 20;
else if (employees >= 20 && employees < 50) score += 5;

// Priority industry
const priorityIndustries = ['media','publishing','saas','software','fintech',
  'financial','consulting','professional services','healthcare','ecommerce',
  'retail','education','biotech','legal','manufacturing'];
if (priorityIndustries.some(i => industry.includes(i))) score += 15;

// Already uses AI
if (/chatgpt|claude|gemini|openai|anthropic/.test(notes)) score += 15;

// Buying trigger
if (/generic|frustrated|context|switch|re-explain|competitor|board|investor|decision/.test(notes)) score += 20;

// Disqualifiers
const isJunk = [
  employees > 0 && employees < 20,
  /\b(ml engineer|data scientist|researcher|phd|student|intern)\b/.test(title),
  /implementation|build for us|develop for/.test(notes),
  /\b(slack integration|email integration|calendar sync)\b/.test(notes)
].some(Boolean);

if (isJunk) score = 0;

const tier = score >= 80 ? 1 : score >= 50 ? 2 : 3;

// Track routing
let track = 'advisory_sales';
let venture_id = 'mindmaker';
let workstream = 'advisory_sales';
let group_label = 'Mindmaker';

const source_type = (d.source_type || '').toLowerCase();
if (source_type === 'podcast') {
  track = 'podcast_booking';
  venture_id = 'media';
  workstream = 'podcast_booking';
  group_label = 'Media';
} else if (source_type === 'content' && score < 85) {
  track = 'nurture';
  venture_id = 'audience';
  workstream = 'nurture';
  group_label = 'Audience';
} else if (d.wants_beta) {
  track = 'beta_cohort';
  venture_id = 'ctrl';
  workstream = 'beta_cohort';
  group_label = 'CTRL Beta';
}

// Identify primary tension
let primary_tension = 'none';
if (/decision|direction|committing|board|strategy/.test(notes)) primary_tension = 'decision_speed';
else if (/voice|tone|generic|sounds like everyone/.test(notes)) primary_tension = 'voice_drift';
else if (/roi|return|value|results|worth it/.test(notes)) primary_tension = 'ai_roi';
else if (/overwhelm|too much|information|noise/.test(notes)) primary_tension = 'information_overload';

// Spread d to top level so downstream nodes can read $json.first_name etc directly
return {
  ...d,
  icp_score: score,
  tier,
  track,
  venture_id,
  workstream,
  group_label,
  primary_tension
};

const resp = $input.item.json;
let draft = { subject: '', body: '', type: 'email' };
try {
  const content = resp.content?.[0]?.text || resp.choices?.[0]?.message?.content || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) draft = JSON.parse(jsonMatch[0]);
} catch(e) {
  draft.body = 'Draft generation failed. Please write manually.';
}

// Retrieve upstream scored data from the ICP node
const scored = $('ICP Score and Route').item.json;

const evidence = draft.type === 'guest_brief'
  ? draft.body
  : `Subject: ${draft.subject}\n\n${draft.body}`;

return {
  ...scored,
  draft_subject: draft.subject,
  draft_body: draft.body,
  evidence,
  task_title: `Review ${scored.group_label} for ${scored.first_name} ${scored.last_name} (${scored.title}, ${scored.company})`
};
